"""Build five immutable H3 R2V shots using the adopted purple poison chikuwa."""
import hashlib,json,shutil,subprocess,sys,zipfile
from pathlib import Path
EP=Path(__file__).resolve().parent
ROOT=EP.parents[1]
SCRIPTS=ROOT/'.claude/skills/minimax-h3-video/scripts'
IDENTITY=(ROOT/'02_CHARACTERS/references/yametaro-identity-prompt.md').read_text().split('```text\n')[1].split('```')[0].replace('[IMAGE REFERENCE]','Yametaro in <Picture 1>')
COMMON='''A widescreen cinematic Japanese backyard BBQ comedy. Exactly three friends in a golden-hour American suburban home backyard, lawn, wood deck, white clapboard house, string lights, charcoal grill and cooler. <Picture 1> is the exact scene composition, identities, proportions, costumes, lighting and prop-state reference. Do not copy a still picture: animate natural small gestures, mouth articulation and smoke. Yotan is the same real Japanese man on LEFT, blond hair, tinted spectacles and black leather jacket, same facial structure and apparent age, no face reshaping. Sobaya is the broad muscular adult in CENTER, short black hair, neutral gray exposed face surround, neck, ears, arms and hands, white fitted T-shirt, brown apron, black pants. His opaque rigid white full-face mask has black round eye holes, long red markings and a black forehead dot. It stays fully fitted during speech, eating and falling; no lifting, slipping, transparency, removal or human-face reveal. The painted mask mouth does not articulate. His voice comes from behind the mask, reactions use head and body. White T-shirt retains broad pectoral shadows and natural cloth wrinkles, continuous cloth over the chest, no nipple points, paired local dark dots or nipple outlines/highlights. Yametaro is the short compact purple-shirted character on RIGHT. Keep his stylized 3D design within this photographic setting; do not humanize him.
Realistic ordinary BBQ food sizes only: mini 4cm chikuwa on skewers, regular 12cm tubes, thick 18cm chikuwa, all clearly hollow tubular fishcakes. Normal chikuwa is cream with brown toasted middle. Poison chikuwa is unmistakably saturated PURPLE through flesh and hollow ends, near-black purple char marks, magenta and small yellow-green mottling, never normal beige/brown. No size growth, giant food or spontaneous extra food. Silver beer cans keep red スーパーつらい and black 労働 / Madogiwa / 生 packaging.
Only the quoted Japanese dialogue, in the stated order. Each speaker finishes before the next begins, except the explicitly simultaneous toast. Non-speakers listen silently without mouthing another person's words. No narrator, captions, superimposed text, laughter track or extra words. Natural grill sizzle, subtle outdoor birds and clothes movement; NO background music (continuous music will be added in edit).'''
CHAPTERS=[
dict(id='ch01',frames=362,image='input_bbq_scene_v2_purple.png',audio=['ch1_yotan.wav','ch1_sobaya.wav','ch1_yametaro.wav'],action='''Locked medium-wide shot as reference: Yotan seated left, Sobaya standing center using tongs in right hand and holding one can in left, Yametaro standing right holding his own can. All remain at these positions. Sobaya gently turns one ordinary cream/brown chikuwa once on grill. Exactly one PURPLE poison chikuwa is already among normal chikuwa, beside tongs, remaining purple throughout. Food is being grilled, not eaten. Yotan looks toward grill and says <d>[Japanese] やっぱバーベキューと言ったら、ちくわだよなー</d>. Audio 1 is Yotan's voice and this exact line. Sobaya responds once behind his unchanged mask <d>[Japanese] この焼き目がいいんですよ！</d>. Audio 2 is Sobaya's voice and exact line. After he finishes Yametaro says with relaxed Kansai intonation <d>[Japanese] 端っこのカリカリがうまいねんな</d>. Audio 3 is Yametaro's voice and exact line. Then relaxed smiles and a small nod. Allow natural conversational pauses, no stretched syllables. No sudden zoom or cuts.'''),
dict(id='ch02',frames=192,image='input_bbq_scene_v2_purple.png',audio=['ch2_sobaya.wav','voice_ref_yotan.wav','voice_ref_yametaro.wav'],action='''Same medium-wide initial positions, all three already hold one can each as image. Sobaya rests his right-hand tongs safely on the grill edge, keeps his left-hand silver can. All three raise their existing cans toward the center in a casual toast without exchanging props. Sobaya calls <d>[Japanese] 乾杯！</d> using Audio 1 as exact line and voice reference. Yotan and Yametaro cheer <d>[Japanese] 乾杯！</d> together in response. Audio 2 is ONLY Yotan's voice-timbre reference, Audio 3 ONLY Yametaro's voice-timbre reference, their source words must NOT be spoken; the only word each says is 乾杯. Cans lightly clink, everyone lowers them, relaxed shared smiles. Sobaya does not drink through his mask. No eating or discovery of poison yet. Keep the purple chikuwa purple and normal ones cream/brown. A large beer mug remains on the table, do not create more mugs.'''),
dict(id='ch03',frames=294,image='input_bbq_lawn_v2_purple.png',audio=['ch3_sobaya.wav','ch3_yotan.wav'],action='''Start with the lawn full-body composition of Picture 1: Yotan now standing left, Sobaya center holding exactly ONE purple cooked chikuwa in right-hand chopsticks and an EMPTY paper plate in left hand, Yametaro right holding his bag. Grill safely at far left. Sobaya proudly looks at his purple chikuwa and says <d>[Japanese] これ、いい感じに焼けました</d>. Audio 1 is his exact line and voice. Afterward Yotan replies <d>[Japanese] お、うまそう</d>. Audio 2 is his exact line and voice. Sobaya then eats the purple chikuwa: cut to a tight rear shoulder angle that occludes the lower face and hand-to-mouth contact behind his near shoulder. Raise the same chopsticks with the same purple chikuwa toward the covered mouth position, brief natural eating sounds, never show an unmasked face or a moving mask. This is deliberate camera occlusion, not mask removal. End by returning to original lawn shot: Sobaya upright, EMPTY chopsticks lowered and EMPTY paper plate, the one purple chikuwa has been eaten and does not reappear. Other two listen, still unaware. Yametaro's bag retains its purple packaged chikuwa. Nobody falls yet. No new words.'''),
dict(id='ch04',frames=260,image='input_bbq_after_eating_v1.png',audio=['ch4_yametaro.wav','ch4_yotan.wav'],action='''Locked lawn full-body three-shot. The purple chikuwa has ALREADY been eaten before this clip: Sobaya has empty chopsticks and an empty paper plate, remains standing silently throughout. Yametaro looks down at the clear food bag already in his hands, then raises the SAME bag slightly to show its 毒ちくわ label and purple contents. He casually recognizes his own purchase and says <d>[Japanese] あ、これワイが買った毒ちくわや！</d>. Audio 1 is his exact line and voice. After he finishes, Yotan turns toward Yametaro, incredulous, and replies <d>[Japanese] なんで買ってるんだよ</d>. Audio 2 is his exact line and voice. Yotan then turns his gaze toward Sobaya. Pause on Sobaya still upright, rigid white mask unchanged. No eating, falling, new food, extra dialogue or screaming. Purple food stays inside the bag, no purple food in Sobaya's hands.'''),
dict(id='ch05',frames=294,image='input_bbq_after_eating_v1.png',audio=['ch5_sobaya.wav'],action='''Final continuous locked WIDE full-body lawn shot, camera far enough to show Sobaya landing on lawn. Initial pose exactly Picture 1, Sobaya stands upright center with EMPTY chopsticks and EMPTY paper plate after eating the purple chikuwa. Yotan stands left and Yametaro right, quiet. Sobaya gives a small authoritative nod and says in his calm matter-of-fact voice exactly once <d>[Japanese] これ、毒ちくわです</d>. Audio 1 is his exact line and voice reference. IMPORTANT temporal order: finish the entire sentence while still upright, hold ONE silent comic beat, THEN his knees suddenly buckle and his upper body tips forward-right and collapses onto the OPEN FOREGROUND LAWN, not into grill or other people. His lightweight paper plate and chopsticks fall harmlessly to the grass. Show his entire body reaching ground in a single fall; finish lying still on his side with white mask still properly fitted and visible. No standing up, second fall, body duplication, disappearing, transformation, wound or blood. Yotan and Yametaro stay standing and silently look down at Sobaya, astonished but same faces. Yametaro keeps opaque white spectacle lenses, no invented eyes. A single dull body thud, then only grill sizzle and a brief silent reaction hold. NO music, screams, groans, extra punchline, dialogue or fade within generated clip; final fade added in edit.''')
]
def main():
    job=EP/'generated/h3-bbq-v1'
    job.mkdir(parents=True,exist_ok=False);bundle=job/'bundle';bundle.mkdir()
    for index,ch in enumerate(CHAPTERS):
        prompt='\n\n'.join([f'Duration {ch["frames"]/24:.3f} seconds, 24fps.',COMMON,IDENTITY,ch['action']])+'\n'
        (EP/f'prompt_{ch["id"]}_v1.txt').write_text(prompt)
        (bundle/f'{ch["id"]}.txt').write_text(prompt)
        for asset in [ch['image'],*ch['audio']]:shutil.copy2(EP/asset,bundle/asset)
        args=[sys.executable,str(SCRIPTS/'build_workflow.py'),'--mode','r2v','--profile','480p-turbo','--frames',str(ch['frames']),'--seed',str(2026103001+index),'--prefix','video/bbq_'+ch['id'],'--out',str(bundle/(ch['id']+'.json')),'--prompt-file',str(bundle/(ch['id']+'.txt')),'--image',ch['image']]
        for asset in ch['audio']:args+=['--audio',asset]
        subprocess.run(args,check=True)
        ch['seed']=2026103001+index
        shutil.copy2(bundle/(ch['id']+'.json'),EP/(ch['id']+'_workflow.json'))
    (EP/'chapter_plan.json').write_text(json.dumps(CHAPTERS,ensure_ascii=False,indent=2)+'\n')
    shutil.copy2(EP/'chapter_plan.json',bundle/'chapter_plan.json')
    shutil.copy2(EP/'colab_batch.py',bundle/'colab_remote.py')
    for name in ['setup_cuda.py','run_workflow.py']:shutil.copy2(SCRIPTS/name,bundle/name)
    with zipfile.ZipFile(job/'inputs.zip','w',zipfile.ZIP_DEFLATED) as z:
        for p in sorted(bundle.iterdir()):z.write(p,p.name)
    (job/'job.json').write_text(json.dumps({'status':'prepared','bundle_sha256':hashlib.sha256((job/'inputs.zip').read_bytes()).hexdigest()},indent=2)+'\n')
    print('Prepared',job,flush=True)
if __name__=='__main__':main()
